import 'package:flutter/material.dart';

import '../../../../core/design_tokens.dart';

/// `MeusRegistrosScreen`'s permanently-docked search bar (spec-5-1,
/// Acceptance Criteria: "permanently docked at the top of Meus Registros
/// with a trailing funnel icon and is never submitted via a button") —
/// paper-elevated like `EntryRecordCard` (`colorSurfaceElevated`,
/// `radiusMd`, `elevation1`). [onChanged] feeds
/// `EntriesSearchCubit.onQueryChanged` directly on every keystroke — there
/// is no submit button anywhere on this widget, by design (Boundaries).
///
/// The trailing funnel (`Icons.filter_list`) button is a no-op this story
/// (Boundaries/Never: filters are spec-5-2) — still sized to the shared
/// 44pt minimum tap target (`insertionModalTapTargetMin`, UX-DR23) so it
/// reads as a real, future-functional control rather than a disabled
/// placeholder.
class EntriesSearchBar extends StatelessWidget {
  const EntriesSearchBar({required this.onChanged, super.key});

  final ValueChanged<String> onChanged;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        borderRadius: BorderRadius.all(Radius.circular(DesignTokens.radiusMd)),
        boxShadow: DesignTokens.elevation1,
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(
          horizontal: DesignTokens.spacingMd,
        ),
        child: Row(
          children: [
            Expanded(
              child: TextField(
                onChanged: onChanged,
                style: DesignTokens.textBodyMd.copyWith(
                  color: DesignTokens.colorTextPrimary,
                ),
                decoration: InputDecoration(
                  isDense: true,
                  border: InputBorder.none,
                  hintText: 'Buscar nos registros...',
                  hintStyle: DesignTokens.textBodyMd.copyWith(
                    color: DesignTokens.colorTextSecondary,
                  ),
                  contentPadding: const EdgeInsets.symmetric(
                    vertical: DesignTokens.spacingMd,
                  ),
                ),
              ),
            ),
            // spec-5-1 Boundaries: a no-op this story — filters land in
            // spec-5-2.
            SizedBox(
              width: DesignTokens.insertionModalTapTargetMin,
              height: DesignTokens.insertionModalTapTargetMin,
              child: IconButton(
                padding: EdgeInsets.zero,
                onPressed: () {},
                // Review finding: an unlabeled icon-only button gives a
                // screen-reader user no indication of its purpose.
                tooltip: 'Filtros',
                icon: const Icon(
                  Icons.filter_list,
                  color: DesignTokens.colorTextSecondary,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

Widget build(BuildContext context) {
  return MultiBlocProvider(
    providers: [
      BlocProvider.value(value: widget.cubit),
      BlocProvider.value(value: widget.searchCubit),
    ],
    child: Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      body: Column(
        children: [
          const BackArrowHeader(title: 'Meus Registros'),
          Padding(
            padding: const EdgeInsets.fromLTRB(
              DesignTokens.spacingMd,
              DesignTokens.spacingMd,
              DesignTokens.spacingMd,
              0,
            ),
            child: EntriesSearchBar(onChanged: widget.searchCubit.onQueryChanged),
          ),
          Expanded(
            child: BlocConsumer<EntriesSearchCubit, Resource<List<Entry>>>(
              listener: _onSearchStateChanged,
              builder: (context, searchState) {
                // Boundaries: "an empty query reverts to the normal
                // timeline" — `ResourceIdle` is the only variant that
                // falls through to the pre-existing
                // `MeusRegistrosCubit`-driven timeline below; every other
                // variant renders the search surface instead.
                if (searchState is ResourceIdle<List<Entry>>) {
                  return BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
                    builder: (context, state) => switch (state) {
                      MeusRegistrosLoading() =>
                        _showSkeleton
                            ? const _SkeletonList()
                            : const SizedBox.shrink(),
                      MeusRegistrosEmpty() => const _EmptyState(),
                      MeusRegistrosError(message: final message) =>
                        _ErrorState(
                          message: message,
                          onRetry: widget.cubit.loadFirstPage,
                        ),
                      MeusRegistrosLoaded() => _EntryList(
                        state: state,
                        scrollController: _scrollController,
                        onRetryLoadMore: widget.cubit.retryLoadMore,
                        onRetryTap: (entry) => widget.cubit.retry(entry.id),
                        onCardTap: _openDetail,
                      ),
                    },
                  );
                }
                return _SearchResults(
                  state: searchState,
                  showSkeleton: _showSearchSkeleton,
                  onCardTap: _openDetail,
                );
              },
            ),
          ),

